# REF: tests/test_print_beds_slicer.py at c8216ff (cad-exporter), ported by tools/port_ref_suites.py:
# REF's checks verbatim, run against aruco_studio.core. Do not edit by hand.
"""Offline tests: a PrusaSlicer project that MIRRORS PrusaSlicer's own
last-used presets (print_beds presets="slicer") and the black / white
filament slots.

Zach, 2026-10-10: "I wouldn't want you to like set the printer or anything...
if possible it should just let prusa ... open the last one set ... just assume
its MMU and you have to assign a filament number 1 - 5 for the two colors."

Run:  python tests/test_print_beds_slicer.py
"""
from __future__ import annotations

import os
import sys
import tempfile
from pathlib import Path

pass  # REF put its own tree on sys.path here (ported: not needed)

from aruco_studio.server import beds_io as P  # noqa: E402  (core.beds + its file I/O, audit C7)

PASS = 0
FAIL = []


def check(label, condition, detail=""):
    global PASS
    if condition:
        PASS += 1
        print(f"  ok  {label}")
    else:
        FAIL.append(label)
        print(f"FAIL  {label}  {detail}")


# A vendor bundle in miniature: the system presets a user preset inherits.
BUNDLE = """[vendor]
name = Prusa Research
config_version = 9.9.9

[printer:*common*]
bed_shape = 0x0,250x0,250x210,0x210
max_print_height = 220
printer_technology = FFF

[printer:Original Prusa MK4 MMU3 0.6 nozzle]
inherits = *common*
nozzle_diameter = 0.6,0.6,0.6,0.6,0.6
extruder_colour = "";"";"";"";""
printer_model = MK4ISMMU3

[print:0.32mm STRUCTURAL @MK4IS 0.6]
layer_height = 0.32

[filament:Generic PLA @PGIS 0.6]
filament_colour = #FF8000
temperature = 215
"""

# The user's own printer preset: his slot colours, a 0.6 nozzle.
USER_PRINTER = """# generated by PrusaSlicer 2.9.6
inherits = Original Prusa MK4 MMU3 0.6 nozzle
extruder_colour = #2A2A2A;#C0C0C0;#FFFFFF;#FF4F4F;#FBEB7D
nozzle_diameter = 0.6,0.6,0.6,0.6,0.6
printer_settings_id =
"""

INI = """[presets]
filament = Generic PLA @PGIS 0.6
filament_1 = aruco_tags.3mf (Generic PLA @PGIS)
filament_2 = Generic PLA @PGIS 0.6
filament_3 = Generic PLA @PGIS 0.6
filament_4 = Generic PLA @PGIS 0.6
physical_printer = ontario * Original Prusa MK4 MMU3 0.6 nozzle - (Black, Clear, White)
print = 0.32mm STRUCTURAL @MK4IS 0.6
printer = Original Prusa MK4 MMU3 0.6 nozzle - (Black, Clear, White)
"""


def datadir(ini=INI):
    d = tempfile.mkdtemp(prefix="ps_datadir_")
    Path(d, "PrusaSlicer.ini").write_text(ini, encoding="utf-8")
    Path(d, "printer").mkdir()
    Path(d, "printer", "Original Prusa MK4 MMU3 0.6 nozzle - (Black, Clear, White).ini"
         ).write_text(USER_PRINTER, encoding="utf-8")
    return d


def cfg_value(text, key):
    for line in text.splitlines():
        if line.startswith("; %s = " % key):
            return line[len("; %s = " % key):]
    return None


print("last_selected_presets")
d = datadir()
sel = P.last_selected_presets(d)
check("reads the printer PrusaSlicer last used",
      sel["printer"] == "Original Prusa MK4 MMU3 0.6 nozzle - (Black, Clear, White)", sel)
check("reads every filament slot, in order", len(sel["filaments"]) == 5, sel["filaments"])
check("no PrusaSlicer.ini -> None", P.last_selected_presets(tempfile.mkdtemp()) is None)

print("load_selected_profile (mirrored)")
prof = P.load_selected_profile(BUNDLE, sel)
check("the user's preset file wins over its vendor parent (his slot colours)",
      prof.values["extruder_colour"] == "#2A2A2A;#C0C0C0;#FFFFFF;#FF4F4F;#FBEB7D",
      prof.values.get("extruder_colour"))
check("the vendor parent fills what the user file leaves out (bed, height)",
      prof.bed_mm == (250.0, 210.0) and prof.max_height_mm == 220.0)
check("5 extruders, from the 0.6 nozzle list", prof.extruders == 5)
check("a project's temporary slot ('x.3mf (...)') takes a real preset",
      prof.filaments == ["Generic PLA @PGIS 0.6"] * 5, prof.filaments)
check("the physical printer is its name, not 'name * preset'", prof.physical_printer == "ontario")
check("mirrored", prof.mirrored)

print("project_config_text: nothing of ours")
st = P.BedSettings(cells_extruder=1, tile_extruder=2, bed_w_mm=250.0, bed_d_mm=210.0)
cfg = P.project_config_text(prof, st)
check("extruder colours stay PrusaSlicer's (no white / black of ours)",
      cfg_value(cfg, "extruder_colour") == "#2A2A2A;#C0C0C0;#FFFFFF;#FF4F4F;#FBEB7D",
      cfg_value(cfg, "extruder_colour"))
check("filament colour stays the preset's", cfg_value(cfg, "filament_colour") == "#FF8000",
      cfg_value(cfg, "filament_colour"))
check("printer_settings_id = the user's own preset",
      cfg_value(cfg, "printer_settings_id")
      == "Original Prusa MK4 MMU3 0.6 nozzle - (Black, Clear, White)")
check("filament_settings_id = one real preset per slot",
      cfg_value(cfg, "filament_settings_id") == ";".join(['"Generic PLA @PGIS 0.6"'] * 5),
      cfg_value(cfg, "filament_settings_id"))
check("physical printer carried", cfg_value(cfg, "physical_printer_settings_id") == "ontario")
st2 = P.BedSettings(cells_extruder=1, tile_extruder=2, bed_w_mm=200.0, bed_d_mm=200.0)
check("a different dialog bed does not resize PrusaSlicer's printer",
      cfg_value(P.project_config_text(prof, st2), "bed_shape") == "0x0,250x0,250x210,0x210")

print("the vendor path is unchanged (recolours, as before)")
vend = P.load_prusa_profile(BUNDLE, "Original Prusa MK4 MMU3 0.6 nozzle",
                            "0.32mm STRUCTURAL @MK4IS 0.6", "Generic PLA @PGIS 0.6")
vcfg = P.project_config_text(vend, P.BedSettings(tile_extruder=1, cells_extruder=2))
check("vendor profile: tile white on 1, cells black on 2",
      cfg_value(vcfg, "extruder_colour").split(";")[:2] == ["#FFFFFF", "#000000"],
      cfg_value(vcfg, "extruder_colour"))

print("slots")
try:
    P.BedSettings(cells_extruder=2, tile_extruder=2).check()
    check("black and white on one filament is refused", False)
except ValueError as exc:
    check("black and white on one filament is refused", "one colour" in str(exc), exc)
try:
    P.BedSettings(cells_extruder=0, tile_extruder=2).check()
    check("slot 0 is refused", False)
except ValueError:
    check("slot 0 is refused", True)

print("_project_setup(presets='slicer') falls back to NO config, never to ours")
old = os.environ.get("APPDATA")
os.environ["APPDATA"] = tempfile.mkdtemp()            # no PrusaSlicer here
try:
    s_, prof_, _c, warn = P._project_setup(250.0, 210.0, 5.0, 5.0,
                                           {"presets": "slicer", "cells_extruder": 1,
                                            "tile_extruder": 2})
    check("no PrusaSlicer.ini -> no profile at all (PrusaSlicer keeps its own)",
          prof_ is None and any("no project config" in w for w in warn), warn)
finally:
    if old is None:
        os.environ.pop("APPDATA", None)
    else:
        os.environ["APPDATA"] = old

print("\n%d passed, %d failed" % (PASS, len(FAIL)))
sys.exit(1 if FAIL else 0)
